INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(1000, 1, 0, 1, 0, 0, 0, 0, 'Dun Morogh', 'A range of snowy, forested peaks in western Khaz Modan, the highest mountains in the Eastern Kingdoms and the homeland of the dwarves and gnomes. Its glaciers feed the rivers that water the rest of Khaz Modan, and its jagged peaks give the dwarves a limitless supply of ore. Mountains enclose it on every side, and its few passes are watched by dwarven troops.\n\nHere stand Ironforge, carved into the tallest mountain, and Gnomeregan, the gnomes'' city in the western foothills. Gnomeregan has fallen, and its survivors shelter with the dwarves. With Ironforge''s armies busy elsewhere, troggs boil up from below, Dark Iron agents skulk in the hills, and the Frostmane trolls wait for their chance to take back the land they lost.', 'warcraft.wiki.gg: Dun Morogh (introduction, History); warcraft.wiki.gg: Frostmane tribe'),
(1001, 1, 1, 1, 0, 0, 0, 0, 'Coldridge Valley', 'An isolated valley in the south-western corner of Dun Morogh, where young dwarves and gnomes come to begin their training. Grelin Whitebeard keeps a camp at its edge and sends the most promising out into the world.\n\nOnly the tunnel of Coldridge Pass links it to the rest of the mountains, and the road from the valley runs east through Kharanos and up into the peaks to the gates of Ironforge.', 'warcraft.wiki.gg: Coldridge Valley; warcraft.wiki.gg: Dun Morogh (Notable characters)'),
(1002, 1, 1, 2, 0, 0, 0, 0, 'Anvilmar', 'The first settlement of any size in Coldridge Valley, built around a great forge. It bears the name of the Anvilmar line, whose High King Modimus once ruled all the dwarves from Ironforge, before the clans went to war over his throne.', 'warcraft.wiki.gg: Anvilmar; warcraft.wiki.gg: Gates of Ironforge; page text 1914 (War of the Three Hammers)'),
(1003, 1, 1, 3, 0, 0, 0, 0, 'Coldridge Pass', 'The tunnel that links Coldridge Valley with the rest of Dun Morogh, through which the trickle of new dwarven recruits passes on its way to Kharanos. Troggs have infested it, and travellers either run through at full speed or cut their way past.', 'warcraft.wiki.gg: Coldridge Pass'),
(1004, 1, 1, 4, 0, 0, 0, 0, 'Kharanos', 'A bustling little town nestled among the peaks, with a large forge, a gnomish workshop and the famous Thunderbrew Distillery. For all its charm, it is a hub of military activity: wendigo lair in the caves to the west, Frostmane trolls hold Shimmer Ridge to the north-west, and new recruits from Anvilmar report here to begin their adventures in earnest.\n\nKharanos remembers the day a giant Frostmane troll attacked the town and nearly killed every dwarf in it. Only the gnome Lazlo Grindwidget managed to bring it down, and he is honoured as a hero of the town.', 'warcraft.wiki.gg: Kharanos'),
(1005, 1, 1, 5, 0, 0, 0, 0, 'Thunderbrew Distillery', 'The great tavern and brewery of Kharanos, known far and wide for some of the best ale in the world. It belongs to the Thunderbrew family; Ragnar Thunderbrew guards the family''s recipes jealously, and his kin brew from Westfall to Kharanos.\n\nBrewing is close to a sacred tradition among the dwarves, and the Thunderbrews'' rivalry with the Barleybrews of Brewnall Village is one of the oldest feuds in Dun Morogh.', 'warcraft.wiki.gg: Thunderbrew Distillery; warcraft.wiki.gg: Brewnall Village'),
(1006, 1, 1, 6, 0, 0, 0, 0, 'Steelgrill''s Depot', 'A small settlement of miners and engineers just east of Kharanos, where dwarves and gnomes work side by side. Many of its tinkers are refugees from Gnomeregan, still working on the machines they carried out of the fallen city.', 'warcraft.wiki.gg: Steelgrill''s Depot; warcraft.wiki.gg: Gnomeregan'),
(1007, 1, 1, 7, 0, 0, 0, 0, 'Brewnall Village and Iceflow Lake', 'A tiny dwarven village in Chill Breeze Valley, near Gnomeregan, home of the Barleybrew family. Rejold Barleybrew and his kin experiment endlessly to improve on the venerable dwarven brewing tradition, hunting secret ingredients for the ultimate ale.\n\nThey keep a hole clear in the ice of Iceflow Lake beside the village for water and fishing. The islands in the middle of the lake are best avoided: a pack of ravenous wolves led by the worg Timber lives there.', 'warcraft.wiki.gg: Brewnall Village; warcraft.wiki.gg: Iceflow Lake; warcraft.wiki.gg: Dun Morogh (Notable characters)'),
(1008, 1, 1, 8, 0, 0, 0, 0, 'Frostmane Hold', 'The base of the Frostmane ice trolls in the western mountains south of Gnomeregan: a few buildings and a network of caves, heavily guarded by headhunters and hideskinners.\n\nIt is the last seat of a people who once ruled all of Dun Morogh, and the trolls defend it as fiercely as they wage their guerrilla war against the dwarves.', 'warcraft.wiki.gg: Frostmane Hold; warcraft.wiki.gg: Frostmane tribe'),
(1009, 1, 1, 9, 0, 0, 0, 0, 'Shimmer Ridge', 'A ridge in northern Dun Morogh, west of the gates of Ironforge, held by Frostmane trolls in two camps joined by a bridge. They tame boars there and grow shimmerweed, which the dwarves prize for an especially tasty ale.', 'warcraft.wiki.gg: Shimmer Ridge'),
(1010, 1, 1, 10, 0, 0, 0, 0, 'The Gates of Gnomeregan', 'The surface entrance of Gnomeregan, the subterranean capital of the gnomes and the wrought-iron proof of their brilliance, ambition and ingenuity. The dwarves helped build it long ago, and the gnomes shared their knowledge of machines in return.\n\nNow its gates open onto a poisoned ruin. The leper gnomes who stayed behind, maddened and twisted by radiation, wander the slopes outside, and the troggs who brought the city down still hold its halls.', 'warcraft.wiki.gg: Gnomeregan; warcraft.wiki.gg: Dun Morogh (History)'),
(1011, 1, 1, 11, 0, 0, 0, 0, 'The Grizzled Den', 'A large cave system just south-west of Kharanos, home to wendigos, great shaggy beasts that breathe frost and flock together to drive out intruders. Their manes are popular as seat covers, which is reason enough for the dwarves to brave the den.', 'warcraft.wiki.gg: Grizzled Den'),
(1012, 1, 1, 12, 0, 0, 0, 0, 'Misty Pine Refuge', 'A small outpost in the forests of central Dun Morogh, sheltering under the pines. Travellers and hunters stop here between Kharanos and the eastern passes, and the beasts of the mountains are never far away.', 'warcraft.wiki.gg: Misty Pine Refuge'),
(1013, 1, 1, 13, 0, 0, 0, 0, 'Gol''Bolar Quarry', 'A large dig site in south-eastern Dun Morogh, with a small dwarven mining camp beside it. Troggs have overrun the excavation and the mine beneath it, and the miners send for help to clear them out.', 'warcraft.wiki.gg: Gol''Bolar Quarry'),
(1014, 1, 1, 14, 0, 0, 0, 0, 'Amberstill Ranch', 'A ranch off the road to Loch Modan where the Amberstill family raises the great mountain rams the dwarves ride, and sells snowshoe rabbits on the side. A wendigo called Vagash has been preying on the herd.', 'warcraft.wiki.gg: Amberstill Ranch'),
(1015, 1, 1, 15, 0, 0, 0, 0, 'Helm''s Bed Lake and Ironband''s Compound', 'Helm''s Bed Lake, in south-eastern Dun Morogh, is mostly frozen over, though a hole in the ice is always kept open for fresh water. The land around it crawls with wildlife and stray troggs.\n\nSouth of the lake stands Ironband''s Compound, once the home of Sturgy Ironband. Dark Iron dwarves have taken over the abandoned building, and attack anyone who comes close.', 'warcraft.wiki.gg: Helm''s Bed Lake; warcraft.wiki.gg: Ironband''s Compound'),
(1016, 1, 1, 16, 0, 0, 0, 0, 'The Gate Outposts', 'Two dwarven guard stations on the passes east to Loch Modan. South Gate Outpost watches the road to Thelsamar, and its mountaineers have mostly cleared the wildlife around it. North Gate Outpost, on the pass towards the Wetlands, has a harder time: several of its mountaineers have gone missing in the mountains hunting the fiercer beasts.', 'warcraft.wiki.gg: South Gate Outpost; warcraft.wiki.gg: North Gate Outpost; warcraft.wiki.gg: North Gate Pass'),
(1017, 1, 1, 17, 0, 0, 0, 0, 'The Gates of Ironforge', 'The great gates of the dwarven capital, visible from far across Dun Morogh at the top of a long ramp in the centre of the mountains. Inside them stands a huge statue of High King Modimus Anvilmar, the last king to rule all the dwarves.', 'warcraft.wiki.gg: Gates of Ironforge'),
(1018, 1, 1, 18, 0, 0, 0, 0, 'Chill Breeze Valley', 'A T-shaped valley in western Dun Morogh between Gnomeregan and Kharanos. Its east-west road is well travelled, but few go down the north-south branch, where bloodstains and torn carcasses on the snow mark the lairs of ferocious beasts. Many who went hunting them have died.', 'warcraft.wiki.gg: Chill Breeze Valley'),
(1030, 1, 2, 1, 0, 0, 0, 0, 'Grelin and Senir Whitebeard', 'Two dwarves of the Whitebeard family who watch over the mountains for Ironforge. Grelin keeps the camp in Coldridge Valley and sends promising young dwarves and gnomes out into the world. Senir, in Kharanos, is set on rooting out the foothold the ice trolls have regained in the region.', 'warcraft.wiki.gg: Dun Morogh (Notable characters)'),
(1033, 1, 2, 2, 0, 0, 0, 0, 'The Barleybrews', 'The brewing family of Brewnall Village, led by Rejold Barleybrew. They are devoted to discovering the perfect recipe for ale, and send young dwarves into the wilds after secret ingredients and to protect their village from wild animals.', 'warcraft.wiki.gg: Brewnall Village; warcraft.wiki.gg: Dun Morogh (Notable characters)'),
(1050, 1, 3, 1, 0, 0, 0, 0, 'The Fall of Gnomeregan', 'During the Third War, troggs stirred from their sleep by upheavals beneath the titan sites burst up into Gnomeregan. High Tinker Gelbin Mekkatorque, on the advice of his adviser Sicco Thermaplugg, ordered the pressure valves of the city''s great machines opened to flood it with toxic radiation and kill the invaders.\n\nThe radiation killed some troggs and made others stronger. Nearly four in five gnomes died within days. The survivors fled to Ironforge; others became mindless leper gnomes. Thermaplugg, driven mad, declared himself King of Gnomeregan and rules its depths with an army of troggs and lepers. Mekkatorque has never stopped planning to take the city back.', 'warcraft.wiki.gg: Gnomeregan (introduction); warcraft.wiki.gg: Dun Morogh (History)'),
(1051, 1, 3, 2, 0, 0, 0, 0, 'The Frostmane Empire', 'Before the dwarves, Dun Morogh belonged to the Frostmane ice trolls, who split from the Drakkari Empire of Northrend at some point after the Sundering; even scholars do not know how they came so far south. Their empire ruled the frozen peaks until the dwarven armies broke it and drove them into the hills, a shame the warlike trolls have never forgotten.\n\nLong ago, Frostmane raiders came too close to Ironforge and killed Queen Eimear on the road. Now, with Ironforge''s armies away fighting the Alliance''s wars and the troggs, the Frostmane see their chance to restore their lost kingdom, and are content to let dwarves and troggs bleed each other first.', 'warcraft.wiki.gg: Frostmane tribe (History, World of Warcraft); warcraft.wiki.gg: Dun Morogh (History)'),
(1052, 1, 3, 3, 0, 0, 0, 0, 'Children of Uldaman', 'Three thousand years before the Dark Portal, the first gnomes came out of Uldaman and settled in Dun Morogh, surviving the cold and the trolls by their wits and building fortified homes deep in the mountains. Five centuries later, the first dwarves left Uldaman too, drawn by the peaks they had seen on the western horizon, and carved Ironforge beneath the tallest of them.\n\nThe two peoples became friends. The dwarves helped the gnomes build Gnomeregan, and the gnomes shared their machines. In the Second War both joined the Alliance; between dwarven brawn and gnomish brains, the orcs never took either capital. Afterwards, Mekkatorque built the Deeprun Tram so that dwarven soldiers could reach Stormwind if it ever needed them.', 'warcraft.wiki.gg: Dun Morogh (History)');
